<?php
require 'db.php'; if(empty($_SESSION['customer_id'])){header('Location: member-login.php');exit;} $error='';$done=false;
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_valid($_POST['csrf']??''))$error='ページの有効期限が切れました。';else{$stmt=$pdo->prepare('SELECT password_hash FROM customers WHERE id=?');$stmt->execute([(int)$_SESSION['customer_id']]);$hash=$stmt->fetchColumn();$old=input_string($_POST['current_password']??'');$new=input_string($_POST['password']??'');if(!$hash||!password_verify($old,$hash))$error='現在のパスワードが正しくありません。';elseif(strlen($new)<8||strlen($new)>72)$error='新しいパスワードは8〜72文字で入力してください。';elseif($new!==input_string($_POST['password_confirm']??''))$error='確認用パスワードが一致しません。';else{$pdo->prepare('UPDATE customers SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$_SESSION['customer_id']]);$done=true;}}}
?><!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>パスワード変更 | Sora Living</title><link rel="stylesheet" href="style.css"><body><main class="page-shell"><section class="search-section"><h2>パスワード変更</h2><?php if($done):?><p>変更しました。</p><?php endif;?><?php if($error):?><p class="error-message"><?=h($error)?></p><?php endif;?><form method="post" class="contact-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>現在のパスワード<input type="password" name="current_password" required autocomplete="current-password"></label><label>新しいパスワード<input type="password" name="password" minlength="8" maxlength="72" required autocomplete="new-password"></label><label>確認入力<input type="password" name="password_confirm" minlength="8" maxlength="72" required></label><button>変更する</button></form><a href="account.php">マイページへ</a></section></main></body></html>
